        requires
            self.wf(),
            version_upper_bound.instance_id() == self.unbounded_log_instance@.id(),
            forall|i|
                #![trigger local_updates[i]]
                0 <= i < request_ids.len() ==> {
                    &&& #[trigger] local_updates.contains_key(i)
                &&& (forall |i| start <= i <= cur ==> self.contents.contains_key(i))
